-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/umm-al-kitab-3-9.json:
-- Umm al-Kitab 3-9, approved by the teachers (9 October), with the question types
-- released the same evening (match, mouth diagram, tap the letters, listen, and
-- record after hearing the reference). New rows: each opens on its class's week;
-- for Masjid An-Nabawi they are Resources homework with no deadline (0077).
-- Loads homework 203, 204, 205, 206, 207, 208, 209 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (203, 204, 205, 206, 207, 208, 209) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (203, 204, 205, 206, 207, 208, 209));
delete from questions where homework_id in (select id from homeworks where number in (203, 204, 205, 206, 207, 208, 209));

